/**
 * ───────────────────────────────────────────────────────────────────────────────
 * [shadcn registry item · 教学演示件] 生成式 UI Generative UI
 *
 * 来源:uiux-atlas src/content/entries/components/ai-generative-ui/demo/Demo.tsx
 *       (由 scripts/generate-registry.mjs 内联生成;源文件保持不动,重跑生成器即刷新)
 *
 * 诚实标注:这是教学演示件,不是生产组件。原 demo 依赖的三个 @/ 内部模块
 * (@/lib/store 参数 store、@/lib/types 类型、@/components/DemoStage 演示舞台)
 * 在 registry 消费端不可用,已原位改写为「[registry 改写]」注释;文件体内对应的
 * getEntryStore / EntrySchema / DemoStage 引用需按各注释提示替换后,本文件才可编译运行。
 * 它记录的是「本站条目页如何实时驱动参数」,供阅读与改写,不可直接安装即用。
 *
 * 依赖:仅 react(+宿主的 react-dom 渲染);registry item 的 dependencies 留空,
 * 由消费端项目按自身版本声明 react。
 * ───────────────────────────────────────────────────────────────────────────────
 */
import { useEffect, useRef, useState } from "react";
// [registry 改写] 原:import { getEntryStore } from "@/lib/store"; —— 本站内部参数 store(getEntryStore,演示页参数面板 → 舞台的实时数据源),registry 消费端不可用;接入时请改为本地受控 state(useState + props),文件体内的 getEntryStore / store.get / store.subscribe 调用需同步替换。
// [registry 改写] 原:import type { EntrySchema } from "@/lib/types"; —— 本站条目 schema 的 TS 类型(EntrySchema),registry 消费端不可用;接入时请以你自己的参数定义类型内联替代,文件体内的 EntrySchema 注解需同步替换。
// [registry 改写] 原:import DemoStage from "@/components/DemoStage"; —— 本站演示舞台组件(.demo-stage:cssVar 注入点 + 舞台铭牌 + #s= 分享参数恢复),registry 消费端不可用;接入时请以自有舞台容器(如一个 <div>)替代,文件体内的 <DemoStage> 标签需同步替换。

interface DemoProps {
  entryId: string;
  schema: EntrySchema;
}

type Scenario = "weather" | "unknown" | "error";
type Phase = "idle" | "input-streaming" | "input-available" | "output-available" | "output-error";

/* Chat SDK tool.tsx 七态词表(demo 实现 4 态):Pending ○ / Running 🕐 / Completed ✔ / Error ✕
   (另三态 output-denied ✕ / approval-requested 🕐 / approval-responded ✔ 见 mdx) */
const BADGES: Record<string, { label: string; zh: string; glyph: string; tone: string }> = {
  "input-streaming": { label: "Pending", zh: "等待", glyph: "○", tone: "pending" },
  "input-available": { label: "Running", zh: "运行", glyph: "◔", tone: "running" },
  "output-available": { label: "Completed", zh: "完成", glyph: "✔", tone: "done" },
  "output-error": { label: "Error", zh: "错误", glyph: "✕", tone: "error" },
};

const TOOL_NAMES: Record<Scenario, string> = {
  weather: "get_weather",
  unknown: "render_chart",
  error: "get_weather",
};

const ARGS: Record<Scenario, string> = {
  weather: '{ "city": "上海 Shanghai", "unit": "celsius" }',
  unknown: '{ "metric": "weekly_visits", "range": 30 }',
  error: '{ "city": "上海 Shanghai", "unit": "celsius" }',
};

const SPEC_FULL = '{"component":"WeatherCard","props":{"city":"上海 Shanghai","tempC":22,"cond":"多云 Cloudy","hi":26,"lo":18}}';
const SPEC_UNKNOWN_FULL = '{"component":"SparklineCard","props":{"metric":"weekly_visits","points":"[3,5,4,8,7,9]"}}';
const ERR_TEXT = "ToolExecutionError: upstream timeout after 5000 ms";

/* 组件注册表 = 白名单:模型可请求的只有这里列出的名字(调研 15§2.2 安全边界) */
const REGISTRY: Record<string, true> = { WeatherCard: true };

const css = `
.gui-stage { width: min(560px, calc(100% - 24px)); position: relative; }
.gui-scenarios { display: flex; gap: 6px; margin-bottom: 8px; justify-content: flex-end; }
.gui-scenarios button, .gui-run {
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-elev);
  color: var(--text-1);
  font: inherit;
  font-size: 12px;
  padding: 4px 12px;
  cursor: pointer;
}
.gui-scenarios button[aria-pressed="true"] { background: color-mix(in srgb, var(--accent) 12%, transparent); border-color: var(--accent); color: var(--accent); }
.gui-scenarios button:focus-visible, .gui-run:focus-visible, .gui-head:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.gui-card { border: 1px solid var(--border); border-radius: 12px; background: var(--bg-elev); overflow: hidden; }
.gui-head {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  border: 0;
  background: transparent;
  font: inherit;
  padding: 10px 14px;
  cursor: pointer;
  color: var(--text-1);
}
.gui-name { font-family: var(--font-mono, ui-monospace, monospace); font-size: 13px; font-weight: 600; }
.gui-badge {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 10px;
  border-radius: 999px;
  border: 1px solid var(--border);
  color: var(--text-faint);
}
.gui-badge[data-tone="running"] { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 45%, transparent); }
.gui-badge[data-tone="done"] { color: #52c41a; border-color: color-mix(in srgb, #52c41a 45%, transparent); }
.gui-badge[data-tone="error"] { color: #ff4d4f; border-color: color-mix(in srgb, #ff4d4f 45%, transparent); }
.gui-badge[data-tone="pending"] { color: var(--text-faint); }
.gui-badge[data-pulse="true"] { animation: gui-pulse 1.2s ease-in-out infinite; }
@keyframes gui-pulse { 50% { opacity: 0.45; } }
.gui-body { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.25s ease; }
.gui-body[data-open="true"] { grid-template-rows: 1fr; }
.gui-body > div { overflow: hidden; }
.gui-inner { padding: 4px 14px 14px; border-top: 1px solid var(--border); }
.gui-label { font-size: 11px; letter-spacing: 0.04em; color: var(--text-faint); margin: 10px 0 4px; }
.gui-code {
  margin: 0;
  padding: 8px 10px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--text-1) 5%, transparent);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-all;
  min-height: 2.2em;
}
.gui-caret { display: inline-block; width: 7px; height: 13px; translate: 0 2px; background: var(--accent); animation: gui-blink 0.9s steps(1) infinite; }
@keyframes gui-blink { 50% { opacity: 0; } }
/* 渐进填充的天气卡(json-spec 模式的映射产物) */
.gui-result { margin-top: 10px; }
.gui-wx {
  display: grid;
  gap: 2px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
}
.gui-wx-city { font-size: 13px; font-weight: 600; color: var(--text-1); }
.gui-wx-temp { font-size: 28px; font-weight: 650; line-height: 1.2; color: var(--text-1); font-variant-numeric: tabular-nums; }
.gui-wx-cond { font-size: 12px; color: var(--text-faint); }
.gui-wx-hilo { font-size: 12px; color: var(--text-faint); font-variant-numeric: tabular-nums; }
.gui-skeleton { display: grid; gap: 8px; padding: 12px 14px; border: 1px dashed var(--border); border-radius: 10px; }
.gui-sk {
  height: 12px;
  border-radius: 6px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--text-1) 6%, transparent) 35%, color-mix(in srgb, var(--text-1) 14%, transparent) 50%, color-mix(in srgb, var(--text-1) 6%, transparent) 65%);
  background-size: 200% 100%;
  animation: gui-sweep 1.6s linear infinite;
}
@keyframes gui-sweep { to { background-position: -200% 0; } }
.gui-fallback { padding: 10px 12px; border: 1px dashed #ff4d4f; border-radius: 10px; }
.gui-fallback p { margin: 0 0 6px; font-size: 12px; color: #ff4d4f; }
.gui-error { padding: 10px 12px; border: 1px solid color-mix(in srgb, #ff4d4f 40%, transparent); border-radius: 10px; font-size: 12px; color: #ff4d4f; }
.gui-status { margin: 8px 2px 0; font-size: 12px; color: var(--text-faint); }
.gui-hint { position: absolute; left: 12px; bottom: 10px; margin: 0; font-size: 12px; color: var(--text-faint); }
@media (prefers-reduced-motion: reduce) {
  .gui-badge[data-pulse="true"], .gui-caret, .gui-sk { animation: none; }
  .gui-body { transition: none; }
}
`;

const PARAMETERS_REVEAL_MS = 28; // 参数逐字节奏:demo 教学值,未证实

/** 生成式 UI 演示:工具调用七态徽章 + Parameters 随流填充 + 白名单兜底 + json-spec 渐进渲染。 */
export default function Demo({ entryId, schema }: DemoProps) {
  const store = getEntryStore(entryId, schema);
  const [genuiMode, setGenuiMode] = useState(() => store.get("genuiMode") as string);
  const [pendingBadge, setPendingBadge] = useState(() => store.get("pendingBadge") as string);
  const [collapsePolicy, setCollapsePolicy] = useState(() => store.get("collapsePolicy") as string);
  const [allowlist, setAllowlist] = useState(() => store.get("allowlist") as string);
  const [streamProps, setStreamProps] = useState(() => store.get("streamProps") as string);
  const [resultRender, setResultRender] = useState(() => store.get("resultRender") as string);

  const [scenario, setScenario] = useState<Scenario>("weather");
  const [phase, setPhase] = useState<Phase>("idle");
  const [revealed, setRevealed] = useState(""); // Parameters / spec 的已到达前缀
  const [collapsed, setCollapsed] = useState(true);
  const timers = useRef<number[]>([]);

  useEffect(
    () =>
      store.subscribe(() => {
        setGenuiMode(store.get("genuiMode") as string);
        setPendingBadge(store.get("pendingBadge") as string);
        setCollapsePolicy(store.get("collapsePolicy") as string);
        setAllowlist(store.get("allowlist") as string);
        setStreamProps(store.get("streamProps") as string);
        setResultRender(store.get("resultRender") as string);
      }),
    [store],
  );

  const clearTimers = () => {
    for (const t of timers.current) window.clearTimeout(t);
    timers.current = [];
  };
  useEffect(() => () => clearTimers(), []);

  const full = genuiMode === "json-spec" ? (scenario === "unknown" ? SPEC_UNKNOWN_FULL : SPEC_FULL) : ARGS[scenario];

  const run = (sc: Scenario = scenario) => {
    clearTimers();
    setScenario(sc);
    setRevealed("");
    setCollapsed(false);
    setPhase("input-streaming");
    const text = genuiMode === "json-spec" ? (sc === "unknown" ? SPEC_UNKNOWN_FULL : SPEC_FULL) : ARGS[sc];
    let doneAt: number;
    if (streamProps === "on") {
      for (let i = 1; i <= text.length; i++) {
        timers.current.push(window.setTimeout(() => setRevealed(text.slice(0, i)), i * PARAMETERS_REVEAL_MS));
      }
      doneAt = text.length * PARAMETERS_REVEAL_MS + 150;
    } else {
      doneAt = 250;
      timers.current.push(window.setTimeout(() => setRevealed(text), doneAt));
    }
    timers.current.push(window.setTimeout(() => setPhase("input-available"), doneAt));
    timers.current.push(
      window.setTimeout(() => setPhase(sc === "error" ? "output-error" : "output-available"), doneAt + 800),
    );
  };

  // 完成后 AUTO_CLOSE:1s 自动收起(仅一次;reasoning.tsx 同源策略),可手动展开
  useEffect(() => {
    if ((phase === "output-available" || phase === "output-error") && collapsePolicy === "auto") {
      const t = window.setTimeout(() => setCollapsed(true), 1000);
      return () => window.clearTimeout(t);
    }
  }, [phase, collapsePolicy]);

  const done = phase === "output-available" || phase === "output-error";
  const badge = BADGES[phase === "idle" ? "input-streaming" : phase] ?? BADGES["input-streaming"];
  const badgeLabel = phase === "input-streaming" ? pendingBadge : badge.label;
  const streamingReveal = phase === "input-streaming" && streamProps === "on";

  // json-spec 渐进解析:字段值一旦完整(引号闭合)即上卡——半截 spec 也渲染(assistant-ui 语义)
  const spec = genuiMode === "json-spec" ? extractSpec(revealed) : null;

  const wx =
    scenario !== "unknown"
      ? { city: "上海 Shanghai", tempC: 22, cond: "多云 Cloudy", hi: 26, lo: 18 }
      : null;

  const unknownName = scenario === "unknown";
  const renderFallback = unknownName && allowlist === "on" && done;

  const status =
    phase === "idle"
      ? "待运行 Idle — 选择场景并运行 Pick a scenario and run"
      : phase === "input-streaming"
        ? `工具入参/spec 流入中 Streaming input… ${revealed.length}/${full.length}`
        : phase === "input-available"
          ? "参数就绪,等待执行 Input ready — awaiting output"
          : phase === "output-error"
            ? "输出错误 output-error(errorText 优先显示)"
            : unknownName && allowlist === "on"
              ? "完成 Completed — 组件不在白名单,降级渲染 JSON 卡"
              : "完成 Completed";

  return (
    <DemoStage entryId={entryId} schema={schema}>
      <div className="gui-stage">
        <div className="gui-scenarios" role="group" aria-label="场景 Scenario">
          <button type="button" aria-pressed={scenario === "weather"} onClick={() => run("weather")}>天气 weather</button>
          <button type="button" aria-pressed={scenario === "unknown"} onClick={() => run("unknown")}>未知组件 unknown</button>
          <button type="button" aria-pressed={scenario === "error"} onClick={() => run("error")}>错误 error</button>
          <button type="button" className="gui-run" onClick={() => run()}>运行 Run</button>
        </div>

        <div className="gui-card">
          <button
            type="button"
            className="gui-head"
            aria-expanded={!collapsed}
            aria-controls="gui-body"
            onClick={() => setCollapsed((c) => !c)}
          >
            <span className="gui-name">{genuiMode === "json-spec" ? "generative_ui" : TOOL_NAMES[scenario]}</span>
            <span className="gui-badge" data-tone={badge.tone} data-pulse={phase === "input-streaming" || phase === "input-available" ? "true" : undefined}>
              <span aria-hidden="true">{badge.glyph}</span>
              {badgeLabel}
            </span>
          </button>
          <div id="gui-body" className="gui-body" data-open={!collapsed ? "true" : "false"}>
            <div>
              <div className="gui-inner">
                <p className="gui-label">{genuiMode === "json-spec" ? "Spec(流中渐进解析 rendered as fields complete)" : "Parameters"}</p>
                <pre className="gui-code">
                  {revealed}
                  {streamingReveal && <span className="gui-caret" aria-hidden="true" />}
                </pre>

                <div className="gui-result" aria-live="polite">
                  {genuiMode === "json-spec" ? (
                    spec ? (
                      renderFallbackSpec(spec, allowlist, done)
                    ) : (
                      <div className="gui-skeleton" aria-hidden="true">
                        <span className="gui-sk" style={{ width: "55%" }} />
                        <span className="gui-sk" style={{ width: "80%" }} />
                        <span className="gui-sk" style={{ width: "40%" }} />
                      </div>
                    )
                  ) : phase === "output-error" ? (
                    <div className="gui-error" role="alert">{ERR_TEXT}</div>
                  ) : renderFallback ? (
                    <div className="gui-fallback">
                      <p>组件 "SparklineCard" 不在白名单,降级渲染 JSON 卡 Component not in allowlist — JSON fallback</p>
                      <pre className="gui-code">{ARGS[scenario]}</pre>
                    </div>
                  ) : phase === "output-available" ? (
                    resultRender === "raw-json" ? (
                      <pre className="gui-code">{JSON.stringify({ city: "上海 Shanghai", tempC: 22, condition: "多云 Cloudy", hi: 26, lo: 18 }, null, 2)}</pre>
                    ) : (
                      wx && (
                        <div className="gui-wx">
                          <span className="gui-wx-city">{wx.city}</span>
                          <span className="gui-wx-temp">{wx.tempC}°C</span>
                          <span className="gui-wx-cond">{wx.cond}</span>
                          <span className="gui-wx-hilo">最高 H {wx.hi}° · 最低 L {wx.lo}°</span>
                        </div>
                      )
                    )
                  ) : null}
                </div>
              </div>
            </div>
          </div>
        </div>
        <p className="gui-status" aria-live="polite">{status}</p>
      </div>
      <style>{css}</style>
      <p className="gui-hint">徽章词表取 Chat SDK tool.tsx Badges follow the Chat SDK tool.tsx vocabulary · 白名单是唯一渲染边界 The allowlist is the only render boundary</p>
    </DemoStage>
  );
}

interface SpecFields {
  component: string | null;
  props: Record<string, string>;
}

/** 从已到达的前缀里提取已闭合的键值(半截 spec 渐进渲染的教学实现) */
function extractSpec(prefix: string): SpecFields | null {
  if (!prefix) return null;
  const cm = prefix.match(/"component"\s*:\s*"([^"]+)"/);
  const props: Record<string, string> = {};
  const re = /"(\w+)"\s*:\s*"([^"]*)"|(\b\w+)\s*:\s*(-?\d+(?:\.\d+)?)/g;
  for (const m of prefix.matchAll(re)) {
    const key = (m[1] ?? m[3]) as string;
    if (key === "component") continue;
    props[key] = (m[2] ?? m[4]) as string;
  }
  return { component: cm ? (cm[1] as string) : null, props };
}

function renderFallbackSpec(spec: SpecFields, allowlist: string, done: boolean) {
  const known = spec.component !== null && REGISTRY[spec.component] === true;
  if (spec.component !== null && !known && allowlist === "on") {
    return (
      <div className="gui-fallback">
        <p>组件 "{spec.component}" 不在白名单,降级渲染 JSON 卡 Component not in allowlist — JSON fallback</p>
        <pre className="gui-code">{'{"component":"' + spec.component + '", …}'}</pre>
      </div>
    );
  }
  if (spec.component !== null && !known && allowlist === "off" && done) {
    return (
      <div className="gui-fallback">
        <p>白名单已关闭:未注册组件被直接渲染(演示风险)Allowlist off: unregistered component mounted as-is (risk demo)</p>
        <pre className="gui-code">{`<SparklineCard … /> ← 模型请求的组件 model-requested`}</pre>
      </div>
    );
  }
  return (
    <div className="gui-wx">
      <span className="gui-wx-city">{spec.props.city ?? "…"}</span>
      <span className="gui-wx-temp">{spec.props.tempC ? `${spec.props.tempC}°C` : "…"}</span>
      <span className="gui-wx-cond">{spec.props.cond ?? "…"}</span>
      <span className="gui-wx-hilo">{spec.props.hi ? `最高 H ${spec.props.hi}° · 最低 L ${spec.props.lo ?? "?"}°` : "…"}</span>
    </div>
  );
}
